                case SNAGGLEBEAST_HIT_KIND_FORCE_UNIT_DAMAGE: case SNAGGLEBEAST_HIT_KIND_UNIT_DAMAGE_OVERRIDE: *(float *)(hit + 0x2c) = 1.0f; break;
