                FUN_L00_00257470(moby, 0, -1);
                data[0x67] = 0x78;
                trooper_anim_update(moby, data + 0x60);
                if ((u8)moby[0x53] != 2) FUN_00212f90(moby, 2, 0, random_int_between(10, 13));
                if (D_001413D4 == 0x78) FUN_L00_002223f8(0, 1);
